package com.johnny.hotel.extras;import com.johnny.hotel.entity.*;import com.johnny.hotel.mapper.*;import lombok.*;import org.springframework.security.access.AccessDeniedException;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import java.util.*;import java.util.stream.*;
@Component@RequiredArgsConstructor public class ExtrasAccess{private final SysUserMapper users;private final SysRoleMapper roles;public record Actor(Long id,Set<String> roles){public boolean customer(){return roles.equals(Set.of("CUSTOMER"));}public boolean finance(){return roles.contains("FINANCE");}public boolean manager(){return roles.stream().anyMatch(Set.of("MANAGER","OWNER","SUPER_ADMIN")::contains);}public boolean staff(){return roles.contains("STAFF")||manager();}public boolean readable(){return customer()||staff()||finance();}}
 public Actor actor(){var a=SecurityContextHolder.getContext().getAuthentication();if(a==null||!a.isAuthenticated()||!(a.getDetails() instanceof Long id))throw denied();var u=users.selectById(id);var rs=roles.selectRolesByUserId(id).stream().map(SysRole::getRoleCode).collect(Collectors.toSet());if(u==null||!Integer.valueOf(1).equals(u.getStatus())||rs.contains("HR_ADMIN")||rs.isEmpty())throw denied();var actor=new Actor(id,rs);if(!actor.readable())throw denied();return actor;}public void manager(Actor a){if(!a.manager())throw denied();}public void operator(Actor a){if(!a.staff())throw denied();}public AccessDeniedException denied(){return new AccessDeniedException("Guest extras access denied");}}
